def numIslands2(m, n, positions):
    # Helper to convert (r,c) to unique index
    def get_idx(r, c):
        return r * n + c

    parent = {}
    rank = {}
    res = []
    count = 0   # Number of islands
    land = set()

    # 4 directions: up, down, left, right
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # path compression
            x = parent[x]
        return x

    def union(x, y):
        xroot, yroot = find(x), find(y)
        if xroot == yroot:
            return False
        # union by rank for efficiency
        if rank[xroot] < rank[yroot]:
            parent[xroot] = yroot
        else:
            parent[yroot] = xroot
            if rank[xroot] == rank[yroot]:
                rank[xroot] += 1
        return True

    for r, c in positions:
        idx = get_idx(r, c)
        if idx in land:
            res.append(count)
            continue
        parent[idx] = idx
        rank[idx] = 0
        land.add(idx)
        count += 1

        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            nidx = get_idx(nr, nc)
            if 0 <= nr < m and 0 <= nc < n and nidx in land:
                if union(idx, nidx):
                    count -= 1
        res.append(count)
    return res
